font='/usr/share/fonts/truetype/dejavu/DejaVuSans'
def render(n,s):
 im=Image.new('RGB',(1080,1350),'#101f30');d=ImageDraw.Draw(im)
 def text(x,y,txt,size,color='#f8f5ec',bold=False,maxw=936):
  f=ImageFont.truetype(font+('-Bold' if bold else '')+'.ttf',size)
  words=txt.split();lines=[];line=''
  for w in words:
   test=(line+' '+w).strip()
   if d.textlength(test,font=f)>maxw and line:lines.append(line);line=w
   else:line=test
  if line:lines.append(line)
  for line in lines:d.text((x,y),line,font=f,fill=color);y+=int(size*1.28)
  return y
 text(72,48,f'KAPUKAI   /   CAROL WOODS   /   {n:02d}',23,'#e7c17c')
 text(72,114,s['kind'].upper(),22,'#9bded3')
 y=text(72,180,s['title'],62,bold=True)
 y=text(72,y+35,s['body'],31,'#cbd6df')
 top=max(670,y+45)
 d.rounded_rectangle((72,top,1008,top+190),radius=14,fill='#21384c')
 text(100,top+23,s['a'],25,'#e7c17c',True,maxw=880)
 text(100,top+75,'↓',32,'#9bded3')
 text(100,top+120,s['b'],25,'#f8f5ec',True,maxw=880)
 text(72,top+222,s['meaning'],31,bold=True)
 text(72,1120,'INTERVIEW '+s['time']+'  •  PARAPHRASED',22,'#e7c17c')
 text(72,1170,'Interview allegations, not independent findings. Read the source and check the records.',23,'#cbd6df')
 text(72,1280,'kapukai.org/evidence/carol-woods/',22,'#e7c17c')
 im.save(V/f'{n:02d}.png')
for i,s in enumerate(S+separate,1):render(i,s)
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f8f5ec;color:#101f30;font-family:Arial,Helvetica,sans-serif;line-height:1.55}a{color:inherit;text-underline-offset:5px}a:focus-visible,summary:focus-visible{outline:3px solid #087b78;outline-offset:5px}header{padding:24px max(24px,calc((100% - 1120px)/2));border-bottom:1px solid #d8d9d3;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.brand{font-weight:800;letter-spacing:.18em}.wrap{max-width:1120px;margin:auto;padding:0 24px}.hero{background:#101f30;color:#f8f5ec;padding:80px 0}.eyebrow{font-size:12px;letter-spacing:.14em;font-weight:bold;text-transform:uppercase;color:#087b78}.hero .eyebrow{color:#9bded3}h1{font-size:clamp(40px,6.5vw,86px);line-height:1.04;letter-spacing:-.055em;max-width:1050px;margin:24px 0 32px}h1 span{color:#9bded3}h2{font-size:clamp(32px,4.2vw,57px);line-height:1.08;letter-spacing:-.035em;margin:14px 0 25px}h3{font-size:25px;line-height:1.2}.intro{font-size:clamp(18px,2vw,24px);max-width:800px}.note{max-width:850px;color:#c7d3dc;font-size:15px}.actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}.button{display:inline-block;background:#9bded3;color:#101f30;padding:13px 20px;border-radius:5px;text-decoration:none;font-weight:700}.button.secondary{background:transparent;border:1px solid #90a9bc;color:#f8f5ec}.contents{padding:24px 0;border-bottom:1px solid #cdd3cf}.contents .wrap{display:flex;gap:24px;flex-wrap:wrap}.story-heading{padding-top:70px}.scene{display:grid;grid-template-columns:80px minmax(0,1.2fr) minmax(0,1fr);gap:30px;padding:65px 0;border-bottom:1px solid #cdd3cf;scroll-margin-top:20px}.number{font-size:60px;font-weight:bold;color:#087b78;line-height:1}.scene h2{font-size:clamp(30px,3.6vw,48px)}.body{font-size:20px;max-width:650px}.kind{font-size:12px;font-weight:bold;color:#086966;text-transform:uppercase;letter-spacing:.07em}.trace{align-self:center}.flow{background:#101f30;color:#f8f5ec;padding:28px;border-radius:8px;font-size:20px;font-weight:bold}.flow div{padding:7px 0;overflow-wrap:anywhere}.arrow{color:#9bded3;font-size:30px}.takeaway{font-size:18px;font-weight:bold}.source{font-size:14px;display:flex;gap:15px;flex-wrap:wrap}details{margin-top:20px}summary{font-size:15px;font-weight:bold;cursor:pointer;padding:10px 0}details p{font-size:15px;color:#405262}.boundary{padding:32px;border-left:4px solid #087b78;background:#e9eee7;margin:40px 0}.chapter{padding:70px 0}.dark{background:#101f30;color:#f8f5ec}.dark .eyebrow{color:#9bded3}.dark a{color:#9bded3}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.checks h3{color:#9bded3}.checks p{color:#c7d3dc}footer{padding:35px 0;font-size:14px}img{max-width:100%;height:auto}.original{padding-bottom:50px}.original h2{font-size:27px}.original .grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.original .card{padding:20px}.original .wrap{padding:0}.original section{padding:12px 0}.original .time{font-weight:bold}.original .timestamp{padding:12px 0}.original .tag{display:inline-block;margin:5px;padding:4px 8px;background:#e5e9e2}.original .notice{border-left:3px solid #087b78;padding-left:15px}@media(max-width:700px){.hero{padding:48px 0}.scene{grid-template-columns:42px minmax(0,1fr);gap:16px;padding:42px 0}.number{font-size:36px}.trace{grid-column:2}.checks,.original .grid{grid-template-columns:1fr}.body{font-size:18px}.flow{font-size:17px;padding:20px}.boundary{padding:22px}.chapter{padding:45px 0}.wrap{padding:0 20px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.hero,.dark{background:white;color:#101f30}.hero span,.hero .eyebrow,.note,.dark p,.dark h3{color:#101f30}.scene{break-inside:avoid}.actions,nav{display:none}}'''
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The court said no. What happened next? | Carol Woods | Kapukai</title><meta name="description" content="Follow Carol Woods’s account scene by scene: a rejected application, an alleged request to alter a file, continued proceedings and a reported challenge in court. Sources and evidence status at every step."><link rel="stylesheet" href="story.css"></head><body><header><a class="brand" href="https://kapukai.org/">KAPUKAI</a><a href="https://kapukai.org/evidence/">Evidence library</a></header><main><section class="hero"><div class="wrap"><p class="eyebrow">Carol Woods / The sequence she describes</p><h1>The court said no.<br><span>Then, she says, came a request to change the file.</span></h1><p class="intro">A mother. A baby. A social worker who says she refused. Follow the events Woods describes—and the evidence needed to test them.</p><p class="note">This is a visual account of interview allegations, not independent findings. Scenes paraphrase the hosted transcript. The later court confrontation was reported to Woods afterward.</p><div class="actions"><a class="button" href="#story">Follow the story ↓</a><a class="button secondary" href="https://kapukai.org/evidence/carol-woods/transcript.html">Read the transcript</a></div></div></section><nav class="contents" aria-label="Chapters"><div class="wrap"><a href="#story">01 / The mother and baby</a><a href="#missing">02 / The missing documents</a><a href="#meaning">03 / What this would mean</a><a href="#sources">Sources & downloads</a></div></nav><section class="wrap" id="story"><div class="story-heading"><p class="eyebrow">Story 01 / One disputed removal</p><h2>Seven moments.<br>One alleged change of direction.</h2><p>Presented in the sequence Woods describes. Interview timestamps are source locations, not dates of the events.</p></div>'''
def scene(s,i):
 e=escape
 return f'''<article class="scene" id="scene-{i}"><div class="number" aria-hidden="true">{i:02d}</div><div><p class="kind">{e(s['kind'])}</p><h2>{e(s['title'])}</h2><p class="body">{e(s['body'])}</p><p class="source"><a href="https://www.youtube.com/watch?v=Xpshopm7AOU&amp;t={s['sec']}s">Interview {s['time']} ↗</a><a href="story/{i:02d}.png" download>Save this scene</a></p><details><summary>What would test this claim?</summary><p>{e(s['check'])}</p></details></div><div class="trace"><div class="flow" aria-label="Alleged sequence"><div>{e(s['a'])}</div><div class="arrow" aria-hidden="true">↓</div><div>{e(s['b'])}</div></div><p class="takeaway">{e(s['meaning'])}</p></div></article>'''
page=head+''.join(scene(s,i) for i,s in enumerate(S,1))
page+='''<aside class="boundary"><strong>What this sequence does not establish</strong><p>It does not establish that the baby was ultimately removed. At 08:00–08:31, Woods expresses her belief that the child was being sought for another couple. That is her interpretation of motive, not proof of an arrangement or payment. The order, full case record and responses of those involved are needed.</p><a href="https://www.youtube.com/watch?v=Xpshopm7AOU&amp;t=480s">Hear her interpretation · 08:00</a></aside></section><section class="wrap" id="missing"><div class="story-heading"><p class="eyebrow">Story 02 / A separate allegation</p><h2>Remove the evidence.<br>Change what the court can see.</h2><p class="intro">Woods also describes missing documents in other children’s files. These claims must not be merged into the baby’s story as if they were one proven incident.</p></div>'''
page+=''.join(scene(s,i) for i,s in enumerate(separate,8))
page+='''<aside class="boundary"><strong>She says she reported it—and received no response.</strong><p>At 10:22–10:54, Woods describes reporting altered records and missing documents to oversight and senior officials. Complaint copies, acknowledgments and response records would test that account.</p><a href="https://www.youtube.com/watch?v=Xpshopm7AOU&amp;t=622s">Listen · 10:22</a></aside></section><section class="chapter dark" id="meaning"><div class="wrap"><p class="eyebrow">The pattern to investigate</p><h2>Who checks the record<br>before it changes a life?</h2><div class="checks"><div><h3>Before the decision.</h3><p>Trace each claim to its source. Preserve the original, every edit and the evidence that contradicts it.</p></div><div><h3>At the decision.</h3><p>Show which version was used, who authorized the action, and how competing evidence was considered.</p></div><div><h3>After a challenge.</h3><p>Make corrections reach every affected decision. Record a responsible reviewer and a deadline.</p></div></div><p class="note">These are Kapukai’s proposed safeguards. This page does not provide live case verification. Urgent protective action needs recorded reasons and prompt independent review.</p><h3>And the money?</h3><p class="intro">Trace it separately. A care market exists. That alone does not prove why a particular child was removed.</p><p class="note">The CMA’s 2022 study documented problems in the placements market, including high profits among large providers. Establishing a financial motive in Woods’s account requires case-specific contracts, payments and communications.</p><a href="https://www.gov.uk/government/publications/childrens-social-care-market-study-final-report/final-report">Read the CMA’s market findings ↗</a></div></section><section class="chapter wrap" id="sources"><p class="eyebrow">Go deeper / Share the sequence</p><h2>Keep the source attached.</h2><p><a href="story/carol-woods-story-sequence.zip" download>Download the nine-scene visual sequence · PNG</a></p><p><a href="https://kapukai.org/evidence/carol-woods/transcript.html">Timestamped transcript</a> · <a href="https://kapukai.org/evidence/carol-woods/transcript_raw.txt">Raw transcript</a> · <a href="https://www.youtube.com/watch?v=Xpshopm7AOU">Original interview</a></p><p>The supplied transcript contains transcription artifacts. Audio alignment has not been independently checked for this release. No corroborating court records or responses were reviewed for this visual account. Timestamps are approximate. The original source entry is retained below.</p>'''
original=(R/'carol-source-entry.html').read_text()
body=original.split('<body>',1)[1].split('</body>',1)[0]
body=body.replace('href="/evidence/','href="https://kapukai.org/evidence/')
page+='<details class="original"><summary>Original evidence entry and additional allegations</summary>'+body+'</details></section></main><footer class="wrap"><strong>Protect the person. Expose the decision.</strong><p>Kapukai · Visual testimony sequence · 1 November 2026</p></footer></body></html>'
(O/'index.html').write_text(page);(O/'story.css').write_text(css)
(V/'source-map.json').write_text(json.dumps({'source':'https://kapukai.org/evidence/carol-woods/transcript_raw.txt','status':'Paraphrases of uncorroborated interview allegations; audio not independently verified.','scenes':S+separate},indent=2,ensure_ascii=False))
with zipfile.ZipFile(V/'carol-woods-story-sequence.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted(V.glob('*.png')):z.write(p,p.name)
 z.write(V/'source-map.json','source-map.json')
print('Built nine visual scenes, source map, downloadable sequence and responsive page.')
